public class Main {
    public static void main(String[] args) {
        int port = Integer.parseInt(System.getenv().getOrDefault("APP_PORT", "8080"));
        if (port < 1 || port > 65535) throw new IllegalArgumentException("APP_PORT must be 1-65535");
        String token = System.getenv("APP_TOKEN");
        if (token == null || token.isBlank()) throw new IllegalStateException("APP_TOKEN is required");
        System.out.println("Port: " + port);
        System.out.println("Token configured: " + !token.isBlank());
    }
}
